  u.anchor=u.links.map((_,i)=>(i+1)*T.slot+i*T.chip+T.chip/2);
  const hangs=u.solo.length?[{at:u.px[0],kids:u.solo}]:u.groups.map((k,i)=>({at:u.anchor[i],kids:k})).filter(h=>h.kids.length);
  let prev=-Infinity;hangs.forEach(h=>{h.kids.forEach(k=>lay(k,depth+1));h.w=h.kids.reduce((s,k)=>s+k.w,0)+T.gap*(h.kids.length-1);
    h.x=Math.max(h.at-h.w/2,prev+T.gap);prev=h.x+h.w;let x=h.x;h.kids.forEach(k=>{k.lx=x;x+=k.w+T.gap})});
