const RN=["","Family apprenticeship","Gen-Z star kid","College outsider","Engineer","Model / pageant / TV","Worked inside first"];
let hubSel=null;
function drawPipes(){
  const counts={};PL.forEach(r=>r[6].forEach(h=>counts[h]=(counts[h]||0)+1));
  const hubs=Object.entries(counts).filter(([h,c])=>c>=2).sort((a,b)=>b[1]-a[1]);
  const max=hubs[0][1];
  document.getElementById('hubs').innerHTML=hubs.map(([h,c])=>`<button class="hub" data-h="${h}" aria-pressed="${h===hubSel}" title="${h}: ${c} of ${PL.length} actors"><span class="hn">${h}</span><span class="track"><span class="bar" style="width:${(c/max*100).toFixed(1)}%"></span><span class="ct">${c}</span></span></button>`).join('');
  document.querySelectorAll('.hub').forEach(b=>b.onclick=()=>{hubSel=hubSel===b.dataset.h?null:b.dataset.h;drawPipes()});
  const rows=PL.filter(r=>!hubSel||r[6].includes(hubSel));
  document.getElementById('ptb').innerHTML=rows.map(r=>`<tr><td>${r[0]}</td><td class="grp">${RN[r[1]]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${r[5]}</td></tr>`).join('');
  document.getElementById('hubclear').hidden=!hubSel;
}
if(document.getElementById('hubs')){document.getElementById('hubclear').onclick=()=>{hubSel=null;drawPipes()};
drawPipes();}

